package com.example.alarmclock; import android.content.BroadcastReceiver; import android.content.Context; import android.content.Intent; import android.media.Ringtone; import android.media.RingtoneManager; import android.net.Uri; import android.widget.Toast; public class AlarmReceiver extends BroadcastReceiver { @Override public void onReceive(Context c,Intent i){Toast.makeText(c,"Alarm Ringing!",Toast.LENGTH_LONG).show();Uri u=RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM);if(u==null)u=RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION);Ringtone r=RingtoneManager.getRingtone(c,u);if(r!=null)r.play();}}
